import { readFileSync, writeFileSync, mkdirSync } from 'node:fs';
import { resolve, dirname, relative } from 'node:path';

// Source directory must be generated by the installed, stable 0.166.0 CLI:
// codex app-server generate-ts --out <directory>
const source = resolve(process.argv[2] ?? '');
if (!process.argv[2]) throw new Error('Pass a directory generated by Codex 0.166.0.');
const target = resolve('src/protocol/generated');
const visited = new Set();
function copy(file) {
  const input = resolve(source, file);
  if (visited.has(input)) return;
  visited.add(input);
  let contents = readFileSync(input, 'utf8');
  if (!contents.startsWith('// GENERATED CODE!')) throw new Error(`Not generated: ${input}`);
  contents = contents.replace(/from "([^"]+)"/g, (_, dependency) => {
    copy(relative(source, resolve(dirname(input), `${dependency}.ts`)));
    return `from "${dependency}.js"`;
  });
  const output = resolve(target, relative(source, input));
  mkdirSync(dirname(output), { recursive: true });
  writeFileSync(output, contents);
}
for (const file of ['InitializeParams.ts', 'InitializeResponse.ts', 'v2/ThreadStartParams.ts', 'v2/ThreadStartResponse.ts', 'v2/TurnStartParams.ts', 'v2/TurnStartResponse.ts', 'v2/TurnStartedNotification.ts', 'v2/TurnCompletedNotification.ts', 'v2/ConfigReadParams.ts', 'v2/ConfigReadResponse.ts']) copy(file);
console.log(`Imported ${visited.size} generated type files; only .js import extensions normalized for NodeNext.`);
